import { AxisScale } from '@visx/axis';
import React, { useContext } from 'react';

import { RangeSorting } from '../types/range-legend.internal.js';

interface RangeLegendScaleContextProps {
  scale: AxisScale<number>;
  sorting: RangeSorting;
}
export const RangeLegendScaleContext =
  React.createContext<RangeLegendScaleContextProps>(
    {} as RangeLegendScaleContextProps,
  );

export const useScale = () => useContext(RangeLegendScaleContext);
